<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Purple &amp; Gold | Product Management</title>
  <link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root{font-family:'DM Sans',sans-serif;color:#17221e;background:#f5f7f4;font-synthesis:none}*{box-sizing:border-box}body{margin:0;min-height:100vh}button,input,textarea{font:inherit}button{cursor:pointer}.login-wrap{min-height:100vh;display:grid;grid-template-columns:1.05fr .95fr;background:#fbfcfa}.login-art{padding:60px 8vw;background:#1e3b32;color:#f7f7ed;display:flex;flex-direction:column;justify-content:space-between;position:relative;overflow:hidden}.login-art:after{content:'';position:absolute;width:520px;height:520px;border:1px solid #ffffff25;border-radius:50%;right:-150px;bottom:-240px;box-shadow:0 0 0 54px #ffffff08,0 0 0 110px #ffffff08}.brand{font:800 21px Manrope;letter-spacing:-.6px}.brand i{display:inline-block;width:11px;height:11px;background:#d5ed7c;border-radius:3px;margin-right:10px}.art-copy{max-width:540px;position:relative;z-index:1}.eyebrow{font-size:11px;letter-spacing:2px;text-transform:uppercase;color:#b6d67d;font-weight:700}.art-copy h1{font:700 clamp(38px,5vw,66px)/1.05 Manrope;letter-spacing:-2.6px;margin:16px 0}.art-copy p{font-size:16px;color:#c8d2cc;line-height:1.7;max-width:410px}.art-foot{color:#a6b6ad;font-size:12px;position:relative;z-index:1}.login-side{display:grid;place-items:center;padding:32px}.login-card{width:min(390px,100%)}.login-card h2{font:700 30px Manrope;letter-spacing:-1px;margin:0 0 8px}.muted{color:#728078;font-size:14px}.field{display:grid;gap:7px;margin-top:19px}.field label{font-size:12px;font-weight:700;color:#39483f}.field input,.field textarea{border:1px solid #dce3dd;border-radius:9px;padding:12px 13px;background:#fff;outline:none}.field input:focus,.field textarea:focus{border-color:#668e55;box-shadow:0 0 0 3px #668e551a}.primary{border:0;border-radius:8px;background:#315c42;color:white;padding:12px 16px;font-weight:700}.primary:hover{background:#244a34}.login-button{width:100%;margin-top:23px}.error{color:#a54134;font-size:13px;margin-top:12px}.shell{max-width:1180px;padding:32px 28px 60px;margin:auto}.topbar{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #e2e8e2;padding-bottom:24px}.topbrand{font:800 19px Manrope}.topbrand i{display:inline-block;width:10px;height:10px;background:#668e55;border-radius:3px;margin-right:9px}.top-actions{display:flex;align-items:center;gap:17px}.logout{border:1px solid #dce3dd;background:white;border-radius:8px;padding:9px 13px;color:#344139;font-size:13px;font-weight:700}.welcome{padding:34px 0 23px}.welcome h1{font:700 29px Manrope;letter-spacing:-1px;margin:0 0 6px}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:14px;margin:14px 0}.search{max-width:320px;width:100%;border:1px solid #dce3dd;background:white;border-radius:8px;padding:11px 13px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:20px 0}.stat,.panel{background:white;border:1px solid #e5eae5;border-radius:12px}.stat{padding:17px}.stat small{color:#76827a;font-size:12px}.stat strong{display:block;font:700 24px Manrope;margin-top:8px}.panel{overflow:hidden}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:670px}th{text-align:left;background:#fafbf9;color:#77837a;font-size:10px;text-transform:uppercase;letter-spacing:1px;padding:13px 16px}td{padding:15px 16px;border-top:1px solid #edf0ed;font-size:13px}td strong{font-size:13px}.desc{display:block;max-width:290px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#77837a;margin-top:4px}.badge{background:#eff5e9;color:#4c713f;border-radius:20px;padding:5px 9px;font-size:11px;font-weight:700}.row-actions{display:flex;gap:7px}.subtle{background:#f4f6f3;border:0;border-radius:6px;padding:7px 9px;font-size:12px;color:#46534b}.danger{color:#a54134}.empty{text-align:center;padding:48px 20px;color:#77837a}.modal-bg{position:fixed;inset:0;background:#15221bc2;display:grid;place-items:center;padding:18px;z-index:5}.modal{background:#fff;width:min(490px,100%);border-radius:13px;padding:24px;box-shadow:0 15px 50px #0003}.modal h2{font:700 22px Manrope;margin:0}.modal .field textarea{min-height:86px;resize:vertical}.modal-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:22px}.cancel{border:1px solid #dce3dd;background:white;border-radius:8px;padding:10px 14px}.toast{position:fixed;right:22px;bottom:22px;background:#243f32;color:white;border-radius:9px;padding:13px 17px;box-shadow:0 8px 30px #0002;z-index:10}.toast.bad{background:#993f34}.loading{padding:35px;text-align:center;color:#77837a}@media(max-width:750px){.login-wrap{grid-template-columns:1fr}.login-art{min-height:270px;padding:28px}.art-foot{display:none}.art-copy h1{font-size:38px;margin:10px 0}.art-copy p{font-size:14px;margin-bottom:0}.login-side{padding:38px 25px}.shell{padding:22px 16px}.stats{gap:8px}.stat{padding:12px}.stat strong{font-size:20px}.toolbar{align-items:stretch;flex-direction:column}.toolbar .primary{align-self:flex-start}.top-actions{gap:8px}.top-actions .muted{display:none}}
    /* Purple and gold fallback palette; lakers.css defines the full courtside treatment. */
    :root{color:#231b2d;background:#f8f5ed}.login-wrap,.login-side{background:#f8f5ed}.login-art{background:#552583}.eyebrow{color:#fdb927}.primary{background:#552583}.topbrand i{background:#fdb927}
  </style>
  <link rel="stylesheet" href="/assets/css/lakers.css?v=1">
</head>
<body>
<div id="root"><div class="loading">Loading Stockroom…</div></div>
<script src="https://unpkg.com/react@18/umd/react.production.min.js" crossorigin></script>
<script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js" crossorigin></script>
<script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
<script type="text/babel">
const {useEffect,useMemo,useState}=React;
const API='/api';
function App(){
 const [token,setToken]=useState(()=>sessionStorage.getItem('stockroom_token')||'');
 const [username,setUsername]=useState(()=>sessionStorage.getItem('stockroom_user')||'');
 const [role,setRole]=useState(()=>sessionStorage.getItem('stockroom_role')||'user');
 const [products,setProducts]=useState([]); const [busy,setBusy]=useState(false); const [error,setError]=useState(''); const [toast,setToast]=useState(''); const [query,setQuery]=useState(''); const [editing,setEditing]=useState(null); const [form,setForm]=useState({product_name:'',description:'',price:'',quantity:''});
 const [credentials,setCredentials]=useState({username:'',email:'',password:''}); const [authMode,setAuthMode]=useState('login');
 async function request(path,options={}){const response=await fetch(API+path,{...options,headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{}),...(options.headers||{})}});let body={};try{body=await response.json()}catch{}if(!response.ok)throw Error(body.error||'Request failed.');return body}
 async function load(){setBusy(true);try{const body=await request('/products');setProducts(body.data||[]);setError('')}catch(e){setError(e.message);if(e.message==='Unauthorized'){logout()}}finally{setBusy(false)}}
 useEffect(()=>{if(token)load()},[token]);
 function notify(message){setToast(message);setTimeout(()=>setToast(''),2600)}
 function logout(){sessionStorage.removeItem('stockroom_token');sessionStorage.removeItem('stockroom_user');sessionStorage.removeItem('stockroom_role');setToken('');setUsername('');setRole('user');setProducts([])}
 function acceptSession(result){sessionStorage.setItem('stockroom_token',result.token);sessionStorage.setItem('stockroom_user',result.username);sessionStorage.setItem('stockroom_role',result.role||'user');setUsername(result.username);setRole(result.role||'user');setToken(result.token)}
 async function login(e){e.preventDefault();setError('');setBusy(true);try{acceptSession(await request('/login',{method:'POST',body:JSON.stringify(credentials)}))}catch(e){setError(e.message)}finally{setBusy(false)}}
 async function register(e){e.preventDefault();setError('');setBusy(true);try{acceptSession(await request('/register',{method:'POST',body:JSON.stringify(credentials)}))}catch(e){setError(e.message)}finally{setBusy(false)}}
 function openForm(product=null){setEditing(product||false);setForm(product?{product_name:product.product_name,description:product.description||'',price:product.price,quantity:product.quantity}:{product_name:'',description:'',price:'',quantity:''})}
 async function save(e){e.preventDefault();setBusy(true);try{await request('/products'+(editing?'/'+editing.id:''),{method:editing?'PUT':'POST',body:JSON.stringify({...form,price:Number(form.price),quantity:Number(form.quantity)})});setEditing(null);await load();notify(editing?'Product updated':'Product added')}catch(e){notify(e.message)}finally{setBusy(false)}}
 async function remove(product){if(!window.confirm('Delete “'+product.product_name+'”? This cannot be undone.'))return;try{await request('/products/'+product.id,{method:'DELETE'});await load();notify('Product deleted')}catch(e){notify(e.message)}}
 const filtered=useMemo(()=>products.filter(p=>(p.product_name+' '+(p.description||'')).toLowerCase().includes(query.toLowerCase())),[products,query]);
 const totalValue=products.reduce((sum,p)=>sum+Number(p.price)*Number(p.quantity),0);
 if(!token)return <main className="login-wrap"><section className="login-art"><div className="brand"><i/>STOCKROOM</div><div className="art-copy"><div className="eyebrow">Courtside inventory</div><h1>Keep your<br/>stock in balance.</h1><p>A quiet place for your catalog, with the resolve to keep every detail in order.</p></div><div className="art-foot">LavaLust API · Aiven MySQL</div></section><section className="login-side"><form className="login-card" onSubmit={authMode==='login'?login:register}><div className="eyebrow" style={{color:'#a65b65'}}>{authMode==='login'?'Welcome back':'Join the inventory'}</div><h2>{authMode==='login'?'Sign in':'Create account'}</h2><p className="muted">{authMode==='login'?'Enter your account details to continue.':'Create an account to manage the product catalog.'}</p><div className="field"><label>Username</label><input autoComplete="username" required value={credentials.username} onChange={e=>setCredentials({...credentials,username:e.target.value})}/></div>{authMode==='register'&&<div className="field"><label>Email</label><input type="email" autoComplete="email" required value={credentials.email} onChange={e=>setCredentials({...credentials,email:e.target.value})}/></div>}<div className="field"><label>Password</label><input type="password" autoComplete={authMode==='login'?'current-password':'new-password'} minLength={authMode==='register'?8:undefined} required value={credentials.password} onChange={e=>setCredentials({...credentials,password:e.target.value})}/></div>{error&&<div className="error">{error}</div>}<button className="primary login-button" disabled={busy}>{busy?(authMode==='login'?'Signing in…':'Creating account…'):(authMode==='login'?'Sign in':'Create account')}</button><div className="account-note">{authMode==='login'?<>New to Stockroom? <button type="button" className="login-switch" onClick={()=>{setError('');setAuthMode('register')}}>Create an account</button></>:<>Already have an account? <button type="button" className="login-switch" onClick={()=>{setError('');setAuthMode('login')}}>Sign in</button></>}</div></form></section></main>;
 return <><main className="shell"><header className="topbar"><div className="topbrand"><i/>STOCKROOM</div><div className="top-actions"><span className="muted">Signed in as <strong>{username}</strong> <span className="role-tag">{role}</span></span><button className="logout" onClick={logout}>Log out</button></div></header><section className="welcome"><div className="eyebrow" style={{color:'#668e55'}}>Inventory overview</div><h1>Products</h1><div className="muted">Manage the items in your catalog.</div></section><section className="stats"><div className="stat"><small>Total products</small><strong>{products.length}</strong></div><div className="stat"><small>Units in stock</small><strong>{products.reduce((n,p)=>n+Number(p.quantity),0).toLocaleString()}</strong></div><div className="stat"><small>Inventory value</small><strong>₱{totalValue.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}</strong></div></section><div className="toolbar"><input className="search" placeholder="Search products…" value={query} onChange={e=>setQuery(e.target.value)}/><button className="primary" onClick={()=>openForm()}>＋ Add product</button></div>{error&&<div className="error" style={{marginBottom:12}}>{error} <button className="subtle" onClick={load}>Retry</button></div>}<section className="panel"><div className="table-wrap"><table><thead><tr><th>Product</th><th>Price</th><th>Quantity</th><th>Added</th><th>Actions</th></tr></thead><tbody>{busy&&!products.length?<tr><td colSpan="5" className="empty">Loading products…</td></tr>:filtered.map(p=><tr key={p.id}><td><strong>{p.product_name}</strong><span className="desc">{p.description||'No description'}</span></td><td>₱{Number(p.price).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}</td><td><span className="badge">{Number(p.quantity)} units</span></td><td>{p.created_at?new Date(p.created_at).toLocaleDateString(): '—'}</td><td><div className="row-actions"><button className="subtle" onClick={()=>openForm(p)}>Edit</button><button className="subtle danger" onClick={()=>remove(p)}>Delete</button></div></td></tr>)}</tbody></table>{!busy&&!filtered.length&&<div className="empty">{query?'No products match your search.':'No products yet. Add your first product to get started.'}</div>}</div></section></main>{editing!==null&&<div className="modal-bg" onMouseDown={e=>{if(e.target===e.currentTarget)setEditing(null)}}><form className="modal" onSubmit={save}><h2>{editing?'Edit product':'Add a product'}</h2><p className="muted">Product details are saved to your catalog.</p><div className="field"><label>Product name</label><input required maxLength="100" value={form.product_name} onChange={e=>setForm({...form,product_name:e.target.value})}/></div><div className="field"><label>Description</label><textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></div><div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:12}}><div className="field"><label>Price (₱)</label><input required min="0" step="0.01" type="number" value={form.price} onChange={e=>setForm({...form,price:e.target.value})}/></div><div className="field"><label>Quantity</label><input required min="0" step="1" type="number" value={form.quantity} onChange={e=>setForm({...form,quantity:e.target.value})}/></div></div><div className="modal-actions"><button type="button" className="cancel" onClick={()=>setEditing(null)}>Cancel</button><button className="primary" disabled={busy}>{busy?'Saving…':editing?'Save changes':'Add product'}</button></div></form></div>}{toast&&<div className="toast">{toast}</div>}</>;
}
ReactDOM.createRoot(document.getElementById('root')).render(<App/>);
</script>
</body>
</html>
